import Foundation
import Observation
import SwiftUI

// MARK: - Catalog (bundled movements.json, generated by backend/scripts/build_movements.py)

struct MovementCatalog: Decodable {
    let version: Int
    let categories: [MovementCategory]
    let movements: [Movement]
}

struct MovementCategory: Decodable, Identifiable, Hashable {
    let id: String
    let name: String
    let blurb: String
    var color: Color { Theme.categoryColor(id) }
}

struct Movement: Decodable, Identifiable, Hashable {
    let id: String
    let name: String
    let english: String
    let category: String
    let level: Int
    let description: String
    let cues: [String]
    let muscles: MuscleSet
    let animation: AnimationSpec
    let aka: [String]?

    static func == (a: Movement, b: Movement) -> Bool { a.id == b.id }
    func hash(into h: inout Hasher) { h.combine(id) }

    var levelName: String { ["", "Beginner", "Intermediate", "Advanced", "Virtuoso"][min(max(level, 0), 4)] }
}

struct MuscleSet: Decodable {
    let primary: [Muscle]
    let secondary: [Muscle]
}

struct AnimationSpec: Decodable {
    let keys: [Keyframe]
    let hero: Int
}

struct Keyframe: Decodable {
    let l: String
    let a: String
    let t: String
    let d: Double
    let yaw: Float?
    let lift: Float?
    let dx: Float?
    let dz: Float?
    let m: Bool?
}

enum Muscle: String, Decodable, CaseIterable, Identifiable {
    case glutes, deep_rotators, quadriceps, hamstrings, adductors, hip_flexors
    case calves, tibialis, foot_intrinsics, core, obliques, erector_spinae
    case lats, deltoids, trapezius, arms

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .glutes: "Glutes"
        case .deep_rotators: "Deep rotators"
        case .quadriceps: "Quadriceps"
        case .hamstrings: "Hamstrings"
        case .adductors: "Inner thighs"
        case .hip_flexors: "Hip flexors"
        case .calves: "Calves"
        case .tibialis: "Shins (tibialis)"
        case .foot_intrinsics: "Foot arches"
        case .core: "Core"
        case .obliques: "Obliques"
        case .erector_spinae: "Back extensors"
        case .lats: "Lats"
        case .deltoids: "Shoulders"
        case .trapezius: "Trapezius"
        case .arms: "Arms"
        }
    }

    /// One line on what the muscle does for a dancer.
    var role: String {
        switch self {
        case .glutes: "Extend the hip and lift arabesque"
        case .deep_rotators: "The six little muscles behind the hip that create turnout"
        case .quadriceps: "Straighten the knee; power for pliés and jumps"
        case .hamstrings: "Lengthen for extensions, bend the knee"
        case .adductors: "Wrap the legs together in fifth and sous-sus"
        case .hip_flexors: "Lift the leg to the front and side"
        case .calves: "Relevé, pointe and every landing"
        case .tibialis: "Control the descent from relevé"
        case .foot_intrinsics: "Articulate and stretch the foot"
        case .core: "Centre, balance and turns"
        case .obliques: "Épaulement, spirals and spotting"
        case .erector_spinae: "Lift the back in arabesque and cambré"
        case .lats: "Support the arms from the back"
        case .deltoids: "Carry the arms"
        case .trapezius: "Keep shoulders down and neck long"
        case .arms: "Soft, rounded port de bras"
        }
    }
}

// MARK: - Library

@Observable
final class MovementLibrary {
    let categories: [MovementCategory]
    let movements: [Movement]
    let poses: PoseLibrary
    private let byID: [String: Movement]

    init(catalog: MovementCatalog, poses: PoseLibrary) {
        self.categories = catalog.categories
        self.movements = catalog.movements
        self.poses = poses
        self.byID = Dictionary(uniqueKeysWithValues: catalog.movements.map { ($0.id, $0) })
    }

    static func load(bundle: Bundle = .main) -> MovementLibrary {
        let poses = PoseLibrary.load(bundle: bundle)
        guard let url = bundle.url(forResource: "movements", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let catalog = try? JSONDecoder().decode(MovementCatalog.self, from: data) else {
            assertionFailure("movements.json missing or invalid")
            return MovementLibrary(catalog: MovementCatalog(version: 0, categories: [], movements: []), poses: poses)
        }
        return MovementLibrary(catalog: catalog, poses: poses)
    }

    func movement(_ id: String) -> Movement? { byID[id] }
    func category(_ id: String) -> MovementCategory? { categories.first { $0.id == id } }

    func movements(in category: String?, matching query: String = "", level: Int? = nil) -> [Movement] {
        let q = query.trimmingCharacters(in: .whitespaces).folding(options: [.diacriticInsensitive, .caseInsensitive], locale: nil)
        return movements.filter { m in
            (category == nil || m.category == category) &&
            (level == nil || m.level == level) &&
            (q.isEmpty || [m.name, m.english, (m.aka ?? []).joined(separator: " ")]
                .joined(separator: " ")
                .folding(options: [.diacriticInsensitive, .caseInsensitive], locale: nil)
                .contains(q))
        }
    }
}
